-- The way in: a causeway that is mostly there, and the staithe where the punt lives.

space {
  id = "di_causeway",
  region = "dithers",
  name = "The Mostly Causeway",
  description = "Beyond the last of the reeds a line of grey stones sets off west across the fen, a yard wide and a hand above the water. It goes straight for a hundred paces. Then there is a stretch of plain brown water with nothing in it, and then the stones begin again as if nothing had happened. On every side the Dithers lies flat to the edge of the sky, shining in some places and green in others, and changing its mind while you watch.",
  ambience = {
    fog { color = "#16262a", speed = 0.1, strength = 0.35 },
    dust { glyphs = "·˙", color = "#5a7468", rate = 0.4, speed = 0.6 },
  },

  things = {
    { name = "the causeway",
      description = "Flat stones laid two by two on a bed of faggots, and under the faggots more faggots, and under those the faggots of people's grandfathers. It sinks a finger's width a year. It has been raised a finger's width a year for six hundred years. The causeway you are standing on is the top of a wall twenty feet high that nobody has ever seen.",
      things = {
        { name = "the stones", description = "Each one cut with the mark of the family that set it: a fish, an eel, a pair of crossed reeds. The marks are sharp for the first few yards and then worn, and then they are a different family's." },
        { name = "the gap",
          key = "di_gap",
          description = "Forty feet of open water where the causeway is not. There are no broken ends. The stones stop square, and start square on the far side, like a sentence somebody has left the middle out of.",
          variants = {
            { when = flag "di_knows_causeway", description = "Forty feet of open water, a hand deep. Now that you have been told, you can see them: the stones are all there, a little under the surface, the same grey as the water. The middle of the causeway has not gone anywhere. It is only being discreet." },
          } },
        { name = "the faggots", description = "Bundles of hazel and alder showing at the edge, black with age, each tied with a withy. There is a boot in among them, and lower down a hat. People lose things off the causeway and the menders, being thrifty, build them in." },
      },
      actions = {
        { "Stamp on it", say "It gives, very slightly, like a mattress. Rings go out across the water on both sides. A long way off, another part of the causeway gives too, and something that was sitting on it says a word." },
      } },
    { name = "the causeway mender",
      icon = "☺",
      description = "A long thin man in waders to the chest, laying a stone at the near end with a wooden beetle. This is Jabez Slodge. He mends from here to the staithe, a yard a day. By the time he reaches the staithe this end has gone down again. He has never caught up and regards catching up as a thing that would do a man no good.",
      things = {
        { name = "his beetle", description = "A mallet with a head the size of a bucket. He lifts it without effort and brings it down without malice. Each stone gets three knocks: one to seat it, one to settle it, and one, he says, so it knows it has been done." },
        { name = "his barrow of stones", description = "Nine, cut and marked with a fish. He brings nine a day from the far side by a way he does not describe. Nobody has seen a quarry in the Dithers. Nobody has seen a hill." },
        { name = "his waders", description = "Greased leather, patched at the knee with more greased leather. There is a high-water mark across the chest, and a higher one, and one at the collar with a date beside it." },
      },
      actions = {
        { "Ask where the middle went", set "di_knows_causeway",
          say "\"Went?\" He looks down the line. \"It's not went. It's under. Stones is all there, same as ever. Water come up over them this morning and it'll go off them by tea.\" He seats a stone. \"You walk it same as the rest. Don't look down, that's all. Them as look down start thinking, and them as start thinking stop.\"" },
        { "Ask if he ever finishes", say "\"Finished Tuesday week,\" he says. \"Got to the staithe. Had a sit.\" He knocks the stone a third time. \"Then I come back to this end and it was Wednesday.\"" },
        { "Offer to help", say "He hands you the beetle. You get it as high as your knee. He takes it back, kindly, and gives you a stone to hold instead, which you do, for some time, until it becomes clear that this was the help." },
      } },
    { name = "the sky",
      wonder = true,
      description = "There is nothing in the Dithers taller than a man, and so there is nothing between you and all of it. The sky comes down to the ground on every side and stands there. {magic}You have lived your whole life under a piece of sky. This is the rest.{/} Weather is going on in four different parts of it, and you can watch a shower set out an hour before it arrives.",
      things = {
        { name = "a shower, coming", description = "A grey curtain a mile wide, walking over the fen on its hem. It will be here by the time you have finished looking at everything else. People in the Dithers do not ask if it will rain. They ask whose it is." },
        { name = "the horizon", description = "Dead level, all the way round, as if ruled. In one place, north and far off, there is a small upright scratch on it. That is a church spire. It is standing in the wrong thing." },
      },
      actions = {
        { "Turn all the way round", say "You turn. There is no direction that is not sky down to your boots. Half way round you put a hand out, as you would on a ladder. There is nothing to hold. You finish the turn anyway and feel that you have been somewhere." },
      } },
    { name = "a signpost",
      description = "An oak post with two arms, standing in the water beside the stones. One arm reads {b}THE DITHERS{/}. The other arm also reads {b}THE DITHERS{/}, and points the other way.",
      things = {
        { name = "a third arm", description = "Lower down, small, and newer: {i}Staithe, when dry. Ask Slodge, when not.{/}" },
        { name = "the flood marks", description = "Notches up the post with dates cut beside them. The highest is above your head. Somebody has cut a small boat beside it." },
      } },
    { name = "the fen on the left",
      description = "Water, brown and clear as tea, a foot deep over black peat. Reeds stand in it. A coot crosses it, running. This morning, Slodge says, a man could have walked there in his slippers.",
      things = {
        { name = "the lilies", description = "White ones, each on a plate of leaf. A frog on one leaf, a blue damselfly on another, each perfectly still, like a shop window." },
        { name = "something moving the reeds", description = "A line of reed heads nods, one after another, as a thing goes by underneath them at walking pace. It reaches the causeway and stops. It is an otter. It was always going to be an otter. You breathe out." },
      } },
    { name = "the fen on the right",
      description = "Grass. Rough, tussocked, with a cow on it. It is exactly as wet as the left side under the grass, and the cow is standing very carefully.",
      things = {
        { name = "the cow", description = "Red, shaggy, and up to the fetlock. She lifts each foot out with a sound like a cork and puts it down somewhere she has thought about. Fen cattle are born knowing the ground. The ones that were not are no longer represented." },
        { name = "a leaping pole", description = "Twelve feet of ash with a round wooden foot, stuck upright by a ditch. Fen people do not go round a ditch. They plant the pole in the middle and go over on it, in an arc, with their hat on.",
          actions = { { "Try a leap", say "You take a run, plant the pole, and rise. For one moment you are upright in the middle of the ditch, perfectly balanced, going neither way. The moment goes on. The cow watches. You come down on the side you started from, which the pole chose, and count it as a draw." } } },
      } },
    { name = "a cart, to the axles",
      description = "A farm cart sunk in the soft verge with its shafts in the air. It has been there long enough to have a wren's nest in the tailboard and a notice.",
      things = {
        { name = "the notice", description = "{i}NOT STUCK. PARKED. E. Turf.{/} The paint is three coats thick. He renews it every spring, at the same time as the cart goes down another inch." },
        { name = "the load", description = "Peat, in black bricks, stacked tight and dry under a hurdle. Good burning. He takes a barrow of it home each week. In this way the cart is being unloaded at about the speed it is sinking, and he says it will come out even." },
      } },
    { name = "bog myrtle",
      description = "Low grey-green bushes along the edge of the stones. You crush a leaf. It smells of resin and something sweeter, and the midges that have been at your neck since the reed beds leave all at once.",
      actions = { { "Put a sprig in your hat", say "You do. The midges form up a yard away and look at you. Jabez Slodge, who has a whole bush in his hatband, nods at you as one professional to another." } } },
    { name = "yellow flags",
      description = "Irises, tall as your waist, in the shallow water. The yellow is the brightest thing in sight. Each flower lasts a day and there has been one open every day since May, like a watch being kept." },
    { name = "a snipe",
      icon = "v",
      description = "A small brown bird with a beak twice too long, climbing into the sky in steps. At the top it turns over and dives, and its tail hums: a soft bleating, like a goat a long way up. It has no song. It plays the air on the way down." },
    { name = "a newt",
      description = "On a wet stone at the causeway's edge, the length of your finger, with an orange belly and a crest like a small dragon's. It looks at you with gold eyes and walks into the water without hurrying, one hand and then the other.",
      actions = { { "Look closer", say "It hangs in the water with its legs out, perfectly at ease. It is, when you come down to it, a dragon. It is a dragon three inches long that eats gnats, and it has no doubts about itself at all." } } },
    { name = "a marsh light",
      icon = "°",
      description = "Pale blue, a foot above the water, some way out. It is not doing anything. When you look at it, it comes a little closer and holds still again, like someone waiting to be asked.",
      actions = {
        { "Ask it the way", say "It goes to the end of the stones, where the water starts, and bobs up and down over the gap. It moves forward a yard, and bobs. It is showing you where the next stone is. It does this for each one, all forty feet, with enormous patience, whether you follow or not." },
      } },
    { name = "the wind",
      description = "It comes across forty miles of nothing and arrives with all its strength, since there has been nothing to spend it on. It smells of wet peat, mint and, faintly, smoke and eels." },
  },

  exits = {
    { to = "reed_beds", label = "Back to the reed beds", description = "East along the stones to the plank walk, the frogs, and the edge of the wood." },
    { to = "di_staithe", label = "Across the gap",
      description = "Over the stretch where the stones are under, and on to the staithe.",
      requires = flag "di_knows_causeway", locked = "the middle of the causeway is not there" },
  },
}

space {
  id = "di_staithe",
  region = "dithers",
  name = "The Staithe",
  description = "The causeway ends at a wharf of black piles and planks, with water on three sides and a dozen channels leading off it into the reeds. This is as far as feet go. A long flat boat is tied at the steps with a man asleep in it, and a duckboard walk sets off to the north on legs, towards a cluster of roofs that seems to be standing in the fen up to its knees.",
  palette = { bg = "#07100f", text = "#c4d0c4", dim = "#5a6e64", accent = "#a8d4b0", border = "#2c4a40" },
  ambience = {
    fog { color = "#13221f", speed = 0.15, strength = 0.45 },
    drip { glyphs = "·˙", color = "#4f8478", rate = 0.2 },
    fireflies { glyphs = "°·", color = "#a8d8e0", rate = 0.1 },
  },

  things = {
    { name = "the punter",
      key = "di_punter",
      icon = "☺",
      description = "Seth Quant, in the stern of his punt with his hat over his face and the pole across his knees. He is the only way to most of the Dithers. He has been asleep, to the best of anyone's knowledge, since his father handed him the pole, and has never yet been late.",
      variants = {
        { when = flag "di_punt_hired", description = "Seth Quant, upright in the stern with the pole in both hands, looking at nothing in particular. He is awake now, in the sense that his eyes are open. The punt is yours for as long as you have somewhere to go." },
      },
      things = {
        { name = "his hat", description = "Felt, green with age, with a band of plaited rush and three eel hooks in it. When it rains he does not move it. The rain goes round." },
        { name = "his hands", description = "Brown, and wider than they are long. The palms are polished like the pole. He holds it as other men hold a walking stick, which is to say he has forgotten it is there." },
      },
      actions = {
        { "Wake him", when = no(flag "di_punt_hired"), set "di_punt_hired",
          say "You cough. Nothing. You say {i}excuse me{/}. Nothing. You step down into the punt, and his eyes open before your second foot is in. \"Fare's a bit of news,\" he says. \"Any news. I don't get about.\" You tell him the King is in a meeting. He thinks about it for some time. \"Still?\" he says, and stands up, and the pole goes in." },
        { "Ask how deep it is", say "\"Depends.\" He puts the pole in. It goes down four feet and stops. He moves it a hand to the left. It goes down twelve and he is holding the last inch. \"Depends,\" he says again, with satisfaction." },
        { "Ask if he ever falls in", say "\"Once.\" He does not go on. You wait. A coot crosses the channel. \"Pole stuck,\" he says at last. \"I'd a choice between the pole and the punt.\" He looks at the pole with great affection. \"Punt come back on its own, about a week after.\"" },
      } },
    { name = "the punt",
      description = "Twenty feet long, flat as a tray, tarred black, with a seat at each end and the middle left open for whatever needs carrying. The name is painted on the side in flaking white: {i}BY AND BY{/}.",
      things = {
        { name = "the pole", description = "A quant, the fen people call it: sixteen feet of ash with an iron shoe at one end and a wooden button at the other for the shoulder. It has been in the mud so many thousand times that the bottom yard is stained black for good." },
        { name = "the bottom boards", description = "Loose, so they can be lifted to bail. Under them: an inch of water, a bailer made from a cow's horn, and an eel, which he says came with the boat." },
        { name = "a cushion", description = "One, for passengers, stuffed with reed mace. It has an embroidered motto: {i}SIT STILL{/}. It is the whole of the safety instructions." },
        { name = "the cargo", description = "Today: two sacks of flour for the village, a coil of rope, a clucking basket, and a parcel of books tied with string, addressed only {i}The Holt, Tuesdays{/}." },
      },
      actions = {
        { "Rock it", say "You shift your weight. The punt does not move at all. It is very wide and very flat and has no opinions. Seth Quant's hat turns towards you by one degree, and you sit still." },
      } },
    { name = "the piles",
      description = "Oak trunks driven into the peat, black and hard as iron, with the planks of the staithe laid over them. The fen keeps wood. These were driven when Aldmoor had no wall, and there is still bark on them below the waterline.",
      things = {
        { name = "the mooring rings", description = "Six, iron, worn thin. Five have a rope end rotting on them. The sixth has the {i}By and By{/}. There used to be more boats, or more places to go." },
        { name = "a water vole", icon = "m", description = "Sitting on a cross-beam just above the water, eating a reed stem lengthways, turning it in both hands. It has a blunt face and no visible neck and looks like a small alderman at a dinner." },
        { name = "freshwater mussels", description = "Clustered on the piles under the surface, each one open a crack. They close as your shadow crosses them, one after another, like shops when the squire's bailiff comes down the street." },
      } },
    { name = "the channels",
      description = "Lodes, they call them: lanes of open water between walls of reed, each just wider than a punt. Twelve leave the staithe. They look exactly alike. Seth Quant can tell them apart by the sound his pole makes on the bottom.",
      things = {
        { name = "the north lode", description = "The widest. It runs beside the duckboards to the village, and there is a painted post every furlong with a lantern hook on it." },
        { name = "the heron's lode", description = "Narrow, overhung with alder. White splashes on the leaves, further in. A great deal of fish has gone down this channel and come back as something else." },
        { name = "the black lode", description = "The water in it is the colour of stout and perfectly clear. It goes south-west to the turf diggings. Bricks of peat have been dropped along its bed, by accident, for so long that it is paved." },
        { name = "the lode with fog in it", description = "It looks like the others for twenty yards. After that it is white, from bank to bank and from the water up, and the reeds on either side go into the white and are not seen to come out." },
        { name = "the lode to the spire", description = "It runs dead north. At the far end of it, small and upright, is the scratch you saw on the horizon. The water in this lode is deeper than the rest. Seth Quant's pole goes in to the button." },
      } },
    { name = "the knot board",
      description = "A plank nailed to a post, with thirty pieces of cord hanging from it, each tied in a row of knots. It is the map of the Dithers. A map on paper would be wrong by Thursday.",
      things = {
        { name = "a cord", description = "You run it through your fingers. A plain knot, two plain knots, a knot with a twist, a loop. {i}Straight, straight, bear left at the willow, open water.{/} You can read it. Nobody taught you. It is that kind of map." },
        { name = "a cord with a new knot", description = "The end has been cut and retied this week. A channel has moved. Under it somebody has chalked: {i}Told you.{/}" },
        { name = "the shortest cord", description = "One knot, pulled tight, and the end burnt off. No one will tell you where that one goes. \"Nowhere,\" says Seth Quant. \"That's what it's the way to.\"" },
      },
      actions = { { "Read one with your eyes shut", say "Knot, knot, twist, loop, a long plain run, and then a knot the size of a nut. You open your eyes. The cord is the one for the village, and the big knot, you understand, is the inn. It is on a slip. It can be slid up and down the cord." } } },
    { name = "the duckboards",
      description = "Planks on trestles, two wide, marching north over water and mud alike with a rope along one side. They have a spring to them. Every tenth trestle carries a post with a number, counting down.",
      things = {
        { name = "a missing plank", description = "Replaced with a door. It still has the knocker." },
        { name = "the rope", description = "Greasy, thick, and hung with small tin bells. In fog you walk with one hand on it. The bells tell the village that somebody is coming, and by the rhythm, who." },
      } },
    { name = "a row of eel traps",
      description = "Long baskets of willow, called hives, drying on the staithe rail with their funnel mouths open. Each has a wooden tally on a string.",
      things = {
        { name = "a tally", description = "Notches for each night's catch. This one runs to forty and then has a deep cross cut through it. Nobody uses that hive any more. It caught something, on the forty-first night, that the owner let go and has never described." },
        { name = "a hive with a hole", description = "Bitten through from inside. The hole is the size of your head. Eels do not bite through willow. This is generally agreed, at some volume, whenever the subject comes up." },
      } },
    { name = "a pike",
      icon = "≺",
      description = "Lying in the shade of the staithe, as long as your leg, green and gold and barred like the reed shadows. It has not moved a fin. Its eye is turned up at you. It has a look you last saw on the Baron's tax collector.",
      actions = { { "Drop a crumb", say "The crumb floats. A small roach comes up for it. There is a movement you do not see and a ring on the water, and the pike is lying exactly where it was, with the same expression and no roach." } } },
    { name = "the sailing notice",
      description = "A board on the end post. {b}PUNT.{/} {i}Leaves: when he's ready. Returns: when he's back. Does not run: never been known.{/}",
      things = {
        { name = "the small print", description = "{i}Passengers are reminded that the fen may differ from the fen as advertised. No refunds, there being no fare. News gratefully received.{/}" },
      } },
    { name = "the water lilies",
      description = "Yellow ones here, brandy-bottles, with a smell of stale wine. Between the leaves the water is so clear and so brown that you can see the stems going down like ropes to a floor of black leaves, and small fish hanging among them in the amber." },
    { name = "a coot",
      description = "Black, with a white shield on its forehead as if it had walked into a wet wall. It is building a nest on the punt's mooring rope. Seth Quant unties from the other end, so as not to disturb her." },
    { name = "a frog with a satchel",
      key = "di_clerk_frog",
      icon = "f",
      description = "On the bottom step, just clear of the water. It is a perfectly ordinary frog except that it has a rolled dock leaf under one arm and an air of being late. It looks at the punt, and at the north lode, and at you, in the manner of somebody who would like a lift and is too proud to ask.",
      actions = {
        { "Offer it a lift", say "You hold out a hand. It steps on, cold and light, and settles on the cushion marked SIT STILL, which it does. \"The spire,\" it does not say. But it faces north the whole time, like a compass, and it has kept hold of the leaf." },
      } },
    { name = "a tide of small silver",
      wonder = true,
      description = "Under the staithe, in the amber water, a ribbon of glass threads is going by against the current: thousands of them, each as long as a finger and clear as a drop, with two black dots for eyes. {magic}They are eels, a year old, come in from the far side of the sea.{/} Nobody has ever seen where they are born. They arrive every spring knowing the way to a ditch they have never been in, and take it.",
      things = {
        { name = "one of them", description = "It stops at a pile, noses it, and goes round. You can see straight through it to the weed. There is a red thread in it, beating. It is going to live in the Dithers for twenty years and then go back to wherever it was, and nobody will see that either." },
      },
      actions = { { "Put a hand in", say "They part round your fingers and close again on the far side without one of them touching you. The ribbon does not slow. It has come three thousand miles. You are not the largest thing it has gone round." } } },
  },

  exits = {
    { to = "di_causeway", label = "The causeway", description = "Back east along the stones, some of which are showing." },
    { to = "di_stilts", label = "The duckboards, north", description = "Along the planks with a hand on the bell rope, to the village on legs." },
    { to = "di_heronry", label = "By punt: the heron's lode", description = "Under the alders, where the leaves are spotted white.",
      requires = flag "di_punt_hired", locked = "the punter is asleep" },
    { to = "di_peat", label = "By punt: the black lode", description = "South-west over the paved channel to the turf diggings.",
      requires = flag "di_punt_hired", locked = "the punter is asleep" },
    { to = "di_fog_lake", label = "By punt: into the fog", description = "Down the lode that goes white.",
      requires = flag "di_punt_hired", locked = "the punter is asleep" },
    { to = "di_spire", label = "By punt: the spire", description = "North by the deep lode, to the church that is standing in the wrong thing.",
      requires = flag "di_punt_hired", locked = "the punter is asleep" },
  },
}
